/**
 * O que não se vê a olho nu — seis mundos dentro do mesmo grão.
 *
 * O slider é a ampliação (10ˣ), e o renderizador já escreve o que se vê em cada
 * faixa. A cena é o campo do microscópio: um círculo que troca de conteúdo
 * conforme a ampliação sobe — grão, gota fervilhando, célula, molécula, átomo,
 * núcleo. Cada estágio é desenhado inteiro, e a transição entre dois vizinhos é
 * um esmaecimento; assim a passagem de escala se sente, em vez de ser lida.
 *
 * A régua lateral mantém a conta à vista: é fácil esquecer que "10⁸×" não é o
 * dobro de "10⁴×", e sim dez mil vezes mais.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  ptBR,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Os seis estágios, no mesmo corte de `medir` do renderizador. */
const ESTAGIOS: readonly (readonly [number, string])[] = [
  [0, 'grão de areia'],
  [1, 'gota de água'],
  [2.5, 'célula'],
  [4, 'molécula'],
  [6, 'átomo'],
  [8, 'núcleo'],
];

/** Pseudoaleatório estável — a mesma partícula no mesmo lugar a cada quadro. */
function semente(i: number, deslocamento = 0): number {
  const v = Math.sin((i + 1) * 12.9898 + deslocamento * 78.233) * 43758.5453;
  return v - Math.floor(v);
}

const microscopio: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** O conteúdo de um estágio, desenhado dentro do campo já recortado. */
  function cena(
    ctx: CanvasRenderingContext2D,
    indice: number,
    cx: number,
    cy: number,
    R: number,
    t: number,
  ): void {
    const cor = paleta();

    if (indice === 0) {
      // O grão: um caco irregular, e mais nada. É o limite do olho nu.
      ctx.fillStyle = '#c9a97a';
      ctx.beginPath();
      for (let i = 0; i <= 11; i++) {
        const ang = (i / 11) * Math.PI * 2;
        const r = R * (0.34 + semente(i) * 0.16);
        const x = cx + Math.cos(ang) * r;
        const y = cy + Math.sin(ang) * r;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#9c7f52';
      ctx.lineWidth = 1.4;
      ctx.stroke();
      return;
    }

    if (indice === 1) {
      // A gota "sem vida": criaturinhas nadando.
      ctx.fillStyle = 'rgb(120 190 235 / 30%)';
      disco(ctx, cx, cy, R * 0.82, ctx.fillStyle);
      for (let i = 0; i < 9; i++) {
        const ang = semente(i) * Math.PI * 2 + t * (0.3 + semente(i, 1) * 0.5);
        const raio = R * (0.15 + semente(i, 2) * 0.55);
        const x = cx + Math.cos(ang) * raio;
        const y = cy + Math.sin(ang) * raio;
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(ang + Math.PI / 2);
        ctx.fillStyle = i % 2 === 0 ? '#3f9c62' : '#8a5fb0';
        ctx.beginPath();
        ctx.ellipse(0, 0, R * 0.045, R * 0.1, 0, 0, Math.PI * 2);
        ctx.fill();
        // O flagelo, batendo.
        ctx.strokeStyle = ctx.fillStyle;
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.moveTo(0, R * 0.1);
        ctx.quadraticCurveTo(Math.sin(t * 8 + i) * R * 0.06, R * 0.18, 0, R * 0.24);
        ctx.stroke();
        ctx.restore();
      }
      return;
    }

    if (indice === 2) {
      // A célula: membrana, núcleo e organelas.
      disco(ctx, cx, cy, R * 0.8, 'rgb(226 164 154 / 55%)');
      ctx.strokeStyle = '#b4655c';
      ctx.lineWidth = 2.4;
      ctx.beginPath();
      ctx.arc(cx, cy, R * 0.8, 0, Math.PI * 2);
      ctx.stroke();

      disco(ctx, cx - R * 0.1, cy - R * 0.08, R * 0.26, '#8a5fb0');
      disco(ctx, cx - R * 0.1, cy - R * 0.08, R * 0.1, '#5f3d80');

      for (let i = 0; i < 7; i++) {
        const ang = semente(i, 3) * Math.PI * 2 + t * 0.2;
        const raio = R * (0.35 + semente(i, 4) * 0.32);
        ctx.save();
        ctx.translate(cx + Math.cos(ang) * raio, cy + Math.sin(ang) * raio);
        ctx.rotate(ang);
        ctx.fillStyle = '#3f9c62';
        ctx.beginPath();
        ctx.ellipse(0, 0, R * 0.11, R * 0.05, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
      return;
    }

    if (indice === 3) {
      // A molécula: a hélice do DNA, que é o exemplo do artigo.
      const passo = R * 0.28;
      for (const fase of [0, Math.PI]) {
        ctx.strokeStyle = fase === 0 ? cor.azul : cor.ouro;
        ctx.lineWidth = 3;
        ctx.beginPath();
        for (let i = 0; i <= 60; i++) {
          const u = i / 60;
          const y = cy - R * 0.72 + u * R * 1.44;
          const x = cx + Math.sin(u * Math.PI * 3 + fase + t * 0.6) * passo;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      }
      ctx.strokeStyle = cor.trilho;
      ctx.lineWidth = 1.6;
      for (let i = 0; i <= 9; i++) {
        const u = i / 9;
        const y = cy - R * 0.72 + u * R * 1.44;
        const dx = Math.sin(u * Math.PI * 3 + t * 0.6) * passo;
        ctx.beginPath();
        ctx.moveTo(cx + dx, y);
        ctx.lineTo(cx - dx, y);
        ctx.stroke();
      }
      return;
    }

    if (indice === 4) {
      // O átomo: a nuvem de elétrons, girando rápido demais para se contar.
      disco(ctx, cx, cy, R * 0.14, cor.erro);
      for (let anel = 0; anel < 3; anel++) {
        const raio = R * (0.34 + anel * 0.2);
        ctx.strokeStyle = cor.trilho;
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.ellipse(cx, cy, raio, raio * (0.35 + anel * 0.15), anel * 1.05, 0, Math.PI * 2);
        ctx.stroke();

        for (let e = 0; e < 2 + anel; e++) {
          const ang = t * (3 - anel * 0.6) + (e / (2 + anel)) * Math.PI * 2;
          const rx = Math.cos(ang) * raio;
          const ry = Math.sin(ang) * raio * (0.35 + anel * 0.15);
          const giro = anel * 1.05;
          disco(
            ctx,
            cx + rx * Math.cos(giro) - ry * Math.sin(giro),
            cy + rx * Math.sin(giro) + ry * Math.cos(giro),
            R * 0.045,
            cor.azul,
          );
        }
      }
      return;
    }

    // O núcleo: prótons e nêutrons empacotados.
    const bolinhas = 9;
    for (let i = 0; i < bolinhas; i++) {
      const ang = (i / bolinhas) * Math.PI * 2 + t * 0.4;
      const raio = i === 0 ? 0 : R * 0.24;
      disco(
        ctx,
        cx + Math.cos(ang) * raio,
        cy + Math.sin(ang) * raio,
        R * 0.16,
        i % 2 === 0 ? cor.erro : cor.fraco,
      );
    }
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const x = limitar(numeroDe(valores, 'x', 0), 0, 9);
    const ok = info.ok === true;
    const miudo = limitar(A * 0.032, 8, 11);

    titulo(ctx, L, A, 'Cada degrau de ampliação abre um mundo');

    // ── O campo do microscópio ────────────────────────────────────────────
    const cx = L * 0.42;
    const cy = A * 0.53;
    const R = Math.min(L * 0.3, A * 0.31);

    disco(ctx, cx, cy, R + 4, cor.trilho);
    disco(ctx, cx, cy, R, cor.contraste);

    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.clip();

    // O estágio atual e o seguinte, cruzando o esmaecimento na fronteira.
    let atual = 0;
    for (const [inicio] of ESTAGIOS) if (x >= inicio) atual++;
    atual = limitar(atual - 1, 0, ESTAGIOS.length - 1);

    const proximo = Math.min(atual + 1, ESTAGIOS.length - 1);
    const inicioAtual = ESTAGIOS[atual]?.[0] ?? 0;
    const inicioProximo = ESTAGIOS[proximo]?.[0] ?? 9;
    const avanco =
      proximo === atual ? 0 : limitar((x - inicioAtual) / (inicioProximo - inicioAtual), 0, 1);
    // Só o último quinto do trecho mistura: antes disso o estágio é ele mesmo.
    const mistura = limitar((avanco - 0.8) / 0.2, 0, 1);

    ctx.globalAlpha = 1 - mistura;
    cena(ctx, atual, cx, cy, R, t);
    if (mistura > 0) {
      ctx.globalAlpha = mistura;
      cena(ctx, proximo, cx, cy, R, t);
    }
    ctx.globalAlpha = 1;
    ctx.restore();

    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.stroke();

    texto(ctx, ESTAGIOS[atual]?.[1] ?? '', cx, cy + R + miudo * 1.8, miudo * 1.2, {
      cor: ok ? cor.verde : cor.texto,
      peso: 800,
    });

    // ── A régua da ampliação ──────────────────────────────────────────────
    const rx = L * 0.86;
    const topo = A * 0.2;
    const altura = A * 0.6;
    const largura = L * 0.06;

    retangulo(ctx, rx - largura / 2, topo, largura, altura, largura / 2, cor.palha, cor.trilho, 1);
    retangulo(
      ctx,
      rx - largura / 2,
      topo + altura - (altura * x) / 9,
      largura,
      (altura * x) / 9,
      largura / 2,
      ok ? cor.verde : cor.azul,
    );

    for (const [inicio, nome] of ESTAGIOS) {
      const y = topo + altura - (altura * inicio) / 9;
      ctx.strokeStyle = cor.trilho;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(rx - largura / 2 - 4, y);
      ctx.lineTo(rx + largura / 2, y);
      ctx.stroke();
      texto(ctx, nome, rx - largura / 2 - 7, y, miudo * 0.85, {
        cor: cor.fraco,
        peso: 600,
        alinhamento: 'right',
      });
    }

    texto(ctx, `${ptBR(Math.round(10 ** x))}×`, rx, topo - miudo * 1.4, miudo * 1.1, {
      cor: ok ? cor.verde : cor.texto,
      peso: 800,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Chegou ao núcleo: 100.000 vezes menor que o átomo ✔',
      'Aumente a ampliação e veja o que havia lá dentro.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default microscopio;
